-- Run against a migrated database. All fixtures and changes are rolled back.
begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; end $$;
insert into auth.users(id,email) values('b103ac16-0000-4000-8000-000000000001','share-a@example.invalid'),('b103ac16-0000-4000-8000-000000000002','share-b@example.invalid');
insert into public.pdfs(id,user_id,title,file_path) values('b103ac16-0000-4000-8000-000000000010','b103ac16-0000-4000-8000-000000000001','Share test lesson','test-only.pdf');
insert into public.notes(id,user_id,content) values('b103ac16-0000-4000-8000-000000000011','b103ac16-0000-4000-8000-000000000001','Standalone lesson');
insert into public.flashcards(id,user_id,question,answer) values('b103ac16-0000-4000-8000-000000000012','b103ac16-0000-4000-8000-000000000001','Q','A');
insert into public.quizzes(id,user_id,pdf_id,title,questions,total_questions) values('b103ac16-0000-4000-8000-000000000013','b103ac16-0000-4000-8000-000000000001','b103ac16-0000-4000-8000-000000000010','Quiz','[{"id":"q1","question":"Q","correctAnswer":"A"}]',1);
set local role authenticated;
select set_config('request.jwt.claim.sub','b103ac16-0000-4000-8000-000000000001',true);
select public.create_study_share('b103ac16-0000-4000-8000-000000000020','pdf','b103ac16-0000-4000-8000-000000000010',null,'Original title','Science','{"text":"Original lesson","flashcards":[],"quizzes":[]}');
select pg_temp.assert_true((select count(*)=1 from public.shared_study_links),'owner can list own share');
select set_config('request.jwt.claim.sub','b103ac16-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.shared_study_links),'other owner cannot list shares');
do $$ begin
 begin perform public.create_study_share(gen_random_uuid(),'pdf','b103ac16-0000-4000-8000-000000000010',null,'Stolen','Science','{"text":"x","flashcards":[],"quizzes":[]}');raise exception 'FAILED cross-owner create allowed';exception when others then if sqlerrm like 'FAILED%' then raise;end if;end;
 begin perform public.revoke_study_share('b103ac16-0000-4000-8000-000000000020');raise exception 'FAILED cross-owner revoke allowed';exception when others then if sqlerrm like 'FAILED%' then raise;end if;end;
end $$;
reset role;
update public.pdfs set title='Changed later' where id='b103ac16-0000-4000-8000-000000000010';
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((select title='Original title' and content_snapshot->>'text'='Original lesson' from public.get_shared_study('b103ac16-0000-4000-8000-000000000020')),'anonymous reads immutable snapshot');
select pg_temp.assert_true((select count(*)=0 from public.get_shared_study('b103ac16-0000-4000-8000-000000000099')),'missing is empty');
select pg_temp.assert_true(not has_table_privilege('anon','public.shared_study_links','SELECT'),'anonymous cannot enumerate');
select pg_temp.assert_true(not has_function_privilege('anon','public.create_study_share(uuid,text,uuid,text,text,text,jsonb)','EXECUTE'),'anonymous cannot publish');
select pg_temp.assert_true(not has_function_privilege('anon','public.revoke_study_share(uuid)','EXECUTE'),'anonymous cannot revoke');
reset role;
update public.shared_study_links set expires_at=now()-interval '1 minute' where share_id='b103ac16-0000-4000-8000-000000000020';
select pg_temp.assert_true((select count(*)=0 from public.get_shared_study('b103ac16-0000-4000-8000-000000000020')),'expired is unavailable');
update public.shared_study_links set expires_at=null where share_id='b103ac16-0000-4000-8000-000000000020';
set local role authenticated;
select set_config('request.jwt.claim.sub','b103ac16-0000-4000-8000-000000000001',true);
do $$ begin
 begin perform public.create_study_share(gen_random_uuid(),'pdf','b103ac16-0000-4000-8000-000000000010',null,'Bad','Science','{"text":"x","flashcards":[],"quizzes":[],"user_id":"private"}');raise exception 'FAILED unknown fields accepted';exception when others then if sqlerrm like 'FAILED%' then raise;end if;end;
 begin update public.shared_study_links set title='Mutated';raise exception 'FAILED snapshot mutation allowed';exception when insufficient_privilege then null;end;
end $$;
select public.revoke_study_share('b103ac16-0000-4000-8000-000000000020');
select pg_temp.assert_true((select count(*)=0 from public.get_shared_study('b103ac16-0000-4000-8000-000000000020')),'revoked is unavailable');
select public.create_study_share('b103ac16-0000-4000-8000-000000000021','pdf','b103ac16-0000-4000-8000-000000000010',null,'Snapshot','Science','{"text":"x","flashcards":[],"quizzes":[]}');
select public.create_study_share('b103ac16-0000-4000-8000-000000000022','note','b103ac16-0000-4000-8000-000000000011',null,'Note','','{"text":"Standalone lesson","flashcards":[],"quizzes":[]}');
select public.create_study_share('b103ac16-0000-4000-8000-000000000023','flashcard','b103ac16-0000-4000-8000-000000000012',null,'Card','','{"text":"","flashcards":[{"question":"Q","answer":"A","explanation":"","options":[]}],"quizzes":[]}');
select public.create_study_share('b103ac16-0000-4000-8000-000000000024','quiz','b103ac16-0000-4000-8000-000000000013','q1','Quiz','','{"text":"","flashcards":[],"quizzes":[{"question":"Q","answer":"A","explanation":"","options":[]}]}');
reset role;
update public.quizzes set questions='[]' where id='b103ac16-0000-4000-8000-000000000013';
select pg_temp.assert_true((select count(*)=0 from public.get_shared_study('b103ac16-0000-4000-8000-000000000024')),'removed question is unavailable');
delete from public.notes where id='b103ac16-0000-4000-8000-000000000011';
delete from public.flashcards where id='b103ac16-0000-4000-8000-000000000012';
select pg_temp.assert_true((select count(*)=0 from public.get_shared_study('b103ac16-0000-4000-8000-000000000022')),'deleted note is unavailable');
select pg_temp.assert_true((select count(*)=0 from public.get_shared_study('b103ac16-0000-4000-8000-000000000023')),'deleted card is unavailable');
delete from public.pdfs where id='b103ac16-0000-4000-8000-000000000010';
select pg_temp.assert_true((select count(*)=0 from public.get_shared_study('b103ac16-0000-4000-8000-000000000021')),'deleted source is unavailable');
rollback;
